import sys

data = sys.stdin.read().split()
s = data[0]
n = len(s)
f = [[0] * n for _ in range(n)]
for ln in range(2, n + 1):
    for i in range(0, n - ln + 1):
        j = i + ln - 1
        if s[i] == s[j]:
            f[i][j] = f[i + 1][j - 1]
        else:
            f[i][j] = 1 + min(f[i + 1][j], f[i][j - 1])
print(f[0][n - 1] if n else 0)

